void mainImage(out vec4 O, vec2 u) {
    vec2 R = iResolution.xy,
        uv = u/R;

    O *= 0.;

    float[] gk1s = float[](
        0.003765, 0.015019, 0.023792, 0.015019, 0.003765,
        0.015019, 0.059912, 0.094907, 0.059912, 0.015019,
        0.023792, 0.094907, 0.150342, 0.094907, 0.023792,
        0.015019, 0.059912, 0.094907, 0.059912, 0.015019,
        0.003765, 0.015019, 0.023792, 0.015019, 0.003765
    );

    //golfed by fabriceneyret2
    for (int k; k < 25; k++)      
        O += gk1s[k] * texture(iChannel0, uv + ( vec2(k%5,k/5) - 2. ) / R );
}

// Wondjina Art visualizer by ORBlivius
//
// Sources: https://www.shadertoy.com/view/wlV3zy 
//          https://www.shadertoy.com/view/fdy3WG
//          https://shadertoy.com/view/Xfy3D3

#define COLS 80
#define ROWS 1

#define COLS_F float(COLS)
#define ROWS_F float(ROWS)

#define CMPR_PAL 1.3
#define FALL 0.02
#define V_OFFS 0.06

float bands[COLS], tops[COLS];

#define CAPS(xx)  (texture(iChannel1, vec2(xx,0.)).r)
#define CAPS1(xx) (bands[int(min(xx * COLS_F, COLS_F))] + V_OFFS)
#define CAPS2(xx) (bands[int(min(xx * COLS_F, COLS_F))])
#define TOPS1(xx) (tops[int(min(xx * COLS_F, COLS_F))] + V_OFFS)
#define TOPS2(xx) (tops[int(min(xx * COLS_F, COLS_F))])

#define R(p, a, r) mix(a * dot(p, a), p, cos(r)) + sin(r) * cross(p, a)
#define H(h) (cos((h) * 6.3 + vec3(0, 23, 21)) * 0.5 + 0.5)
#define PI 3.141592
#define TAU 2.0 * PI
#define hue(v) (0.6 + 0.6 * cos(6.3 * (v) + vec3(0, 23, 21)))
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))
#define COUNT 30.0
#define N 5.0
#define DISTORT 0.7
#define SQR(x) ((x) * (x))

float tt;

// Kaleidoscopic UV distortions
vec2 kalei(vec2 uv) {
    float n = N;
    float r = TAU / n;
    for (float i = 0.0; i < n; i++) {
        uv = abs(uv);
        uv *= rot(r * i - 0.09 * tt);
    }
    uv = abs(uv) - (sin(0.15 * tt) + 1.2);
    return uv;
}

// Flower SDF
float flower(vec2 uv) {
    float n = 5.0;
    float a = atan(uv.y, uv.x);
    float d = length(uv) - cos(a * n);
    return smoothstep(fwidth(d), 0.0, abs(d));
}

// Spiral pattern with distortion
vec3 spiral(vec2 uv, float i) {
    uv *= rot(i  * PI + iTime * 0.33);
     uv += DISTORT * sin(3.0 * uv.xy);
    return flower(uv) * SQR(hue(i + tt * 0.5));
}

float luma(in vec3 color) {
    return dot(color, vec3(0.299, 0.587, 0.114));
}
float sdRoundBox(vec2 p, vec2 b, float r)
{
  vec2 q = abs(p) - b;
  return length(max(q,.0)) + min(max(q.x,q.y),.0) - r;
}

 // returns 3 B-spline functions of degree 2
 vec2 RotateUV(vec2 uv,float angle)
{
    return vec2(uv.x * cos(angle) - uv.y * sin(angle),uv.x * sin(angle) + uv.y *cos(angle));
}
vec3 B2_spline(vec3 x) {
    vec3 t = 3.0 * x;
    vec3 b0 = step(0.0, t)     * step(0.0, 1.0-t);
	vec3 b1 = step(0.0, t-1.0) * step(0.0, 2.0-t);
	vec3 b2 = step(0.0, t-2.0) * step(0.0, 3.0-t);
	return 0.5 * (
    	b0 * pow(t, vec3(2.0)) +
    	b1 * (-2.0*pow(t, vec3(2.0)) + 6.0*t - 3.0) + 
    	b2 * pow(3.0-t,vec3(2.0))
    );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) 
{
    vec2 uv = fragCoord;
    uv.y = iResolution.y - uv.y;

    vec2 uvd = fragCoord.xy / iResolution.xy;
    vec2 nc = vec2(COLS, ROWS);

    if (fragCoord.y <= 1.) 
    {
       float fi = fragCoord.x;
       int i = int(fi);
       bands[i] = texture(iChannel0, vec2(fi / iResolution.x, .5/iResolution.y)).a;
       float val = texture(iChannel1, vec2(fi / iResolution.x, 0.)).r;
       vec4 col = vec4(max(max(bands[i]-FALL,0.),val));
       bands[i] = col.a;
       fragColor = vec4(0,0,0,col.r);
   } else{
        for (float i=0.; i<COLS_F; i++) {
           bands[int(i)] = texture(iChannel0, vec2(i / COLS_F, 0./iResolution.y)).a; 
           tops[int(i)] = texture(iChannel0, vec2(i / COLS_F, .5/iResolution.y)).a; 
        }

        fragColor = vec4(0.0);
        vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
        vec3 col = vec3(0.0);
       // uv = RotateUV(uv, (10.*iTime*.04));
        // Audio Reactivity
        vec2 uv2 = fragCoord.xy/iResolution.xy;

        // Kaleidoscopic UV distortion
        vec3 r2 = normalize(vec3(uv.xy, 1.0 - dot(uv.xy, uv.xy) * 10.0));
        uv = kalei(uv  * 3. + r2.xy);

        // Generate spiral patterns with fading
        float s = 1.0 / COUNT;
        for (float i = 0.0; i < 1.0; i += s) {
             float a1 = pow(bands[int(i * COLS_F)], 2.);
             float a2 = pow(tops[int(i * COLS_F)], 2.);

            float z = fract(i + 0.01 * tt + a1);
            float fade = smoothstep(0.0, 0.2, 1.0 - abs(1.0 * z - 1.0));
             uv = RotateUV(uv, a1);
            col += spiral(abs(a2 - (sin(-iTime*.05))) * uv * fade * max(z , s), (s + .5+a1)) * fade * (1.0 + 0.5 * a2);
        }

       col = sqrt(col); // Enhance glow intensity

        // Add depth and dynamic motion
        vec3 p, r = iResolution, d = normalize(vec3((fragCoord - 0.5 * r.xy) / r.y, 1.0));
        for (float i = 0.0, g = 0.0, e, s; ++i < 60.0; ) {
            p = g * d * pow(col,vec3(4));
            float a2 = .25 * pow(bands[int(i * COLS_F / 60.)], 1.);
            p.z -= abs( -a2 + .3 + .1 * abs(sin(-.35 * a2 + iTime*.1)));

            p = R(p, normalize(vec3(1.0, 1.0, 0.0)), iTime * 0.1);
            p.xy *= rot(i * PI + iTime * 0.1233);
            s = 3.5;
            for (int j = 0; j++ < 6;) {
                p = abs(p);
                p = p.x < p.y ? p.zxy : p.zyx;
                s *= e = 1.35 / min(dot(p, p), 1.35);
                p = p * e - vec3(12.0, 3.0, 3.0);
            }
            g += e = length(p.xz) / s;
            fragColor.rgb += mix(r / r, H(log(s)), 0.6) * 0.3 * exp(-i * i * e);
        }

        // Final color adjustments
        fragColor = pow(fragColor, vec4(4));
    }


}

#define DECAY     .9
#define DENSITY   .1
#define WEIGHT    .015
#define EXPOSURE  .2
#define SAMPLES_COUNT  70

#define LIGHT_SOURCE_TEXTURE iChannel0

#define PI 3.141592

float stepping(float t)
{
    if(t < 0.)
    {
        return -1. + pow(1. + t, 2.);
    }
    else
    {
        return 1. - pow(1. - t , 2.);
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //normalized
    vec2 uv = fragCoord/iResolution.xy;

    vec3 col=vec3(0);
    float snd = texture(iChannel0, uv).r;
    snd = fract(float(int(snd * 20.))/20.);

    vec2 ligthPos = vec2(0.5); //(iMouse.xy == vec2(0.))? vec2(0.5) : iMouse.xy/iResolution.xy;
     ligthPos.x += .2*sin(iTime*1.5)*(snd);
     ligthPos.y += .2*cos(iTime*1.5)*(snd);
     vec2 delta = uv - ligthPos;

    delta *= 1.0 /  float(SAMPLES_COUNT) * DENSITY;

    float illuminationDecay = 1.0;    

    for(int i = 0; i < SAMPLES_COUNT; i++)
    {
        uv -= delta;
		vec4 samp = texture(LIGHT_SOURCE_TEXTURE , uv)*0.4;
		samp *= illuminationDecay * WEIGHT;
		col += samp.rgb;
		illuminationDecay *= DECAY;
    }

    col *= EXPOSURE;

    //output
    fragColor = vec4(col,1.0);
}
